import{_ as r,a0 as l,w as p,s as a,ao as d,I as i,x as s,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"在Linux中的使用 ss 命令检查套接字/网络连接 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux中的使用 ss 命令检查套接字/网络连接 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux中的使用 ss 命令检查套接字/网络连接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux中的使用 ss 命令检查套接字/网络连接 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141017 Linux ss Tool to Identify Sockets or Network Connections with Examples","title":"在Linux中的使用 ss 命令检查套接字/网络连接","tag":"201412","desc":""},"relativePath":"201412/20141017 Linux ss Tool to Identify Sockets or Network Connections with Examples.md","filePath":"[post].md"}'),g={name:"201412/20141017 Linux ss Tool to Identify Sockets or Network Connections with Examples.md"};function u(x,t,m,T,c,f){const n=l("Link");return p(),a("div",null,[t[13]||(t[13]=d(`<h1 id="在linux中的使用-ss-命令检查套接字-网络连接" tabindex="-1">在Linux中的使用 ss 命令检查套接字/网络连接 <a class="header-anchor" href="#在linux中的使用-ss-命令检查套接字-网络连接" aria-label="Permalink to “在Linux中的使用 ss 命令检查套接字/网络连接”">​</a></h1><p>ss是iproute2包的一部分（控制TCP/IP网络和流量的工具）。iproute2的目标是替代先前用于配置网络接口、路由表和管理ARP表的标准Unix网络工具套装（通常称之为“net-tools”）。ss工具用于导出套接字统计，它可以显示与netstat类似的信息，且可以显示更多的TCP和状态信息。因为它直接从内核空间获取信息，所以会更快。ss的操作和netstat很像，所以这让它可以很容易就可以取代。</p><h3 id="使用和常见选项" tabindex="-1">使用和常见选项 <a class="header-anchor" href="#使用和常见选项" aria-label="Permalink to “使用和常见选项”">​</a></h3><p>ss和netstat很像，默认它会显示已经建立连接的开放的非监听TCP套接字列表。并且你可以用下面的选项过滤输出：</p><ul><li><strong>-n</strong> - 不要尝试解析服务名。</li><li><strong>-r</strong> - 尝试解析数字的地址/端口。</li><li><strong>-a</strong> - 显示所有套接字。</li><li><strong>-l</strong> - 显示监听套接字。</li><li><strong>-p</strong> - 显示使用该套接字的进程。</li><li><strong>-s</strong> - 打印统计数据</li><li><strong>-t</strong> - 只显示TCP套接字。</li><li><strong>-u</strong> - 只显示UDP套接字。</li><li><strong>-d</strong> - 只显示DCCP套接字</li><li><strong>-w</strong> - 只显示RAW套接字。</li><li><strong>-x</strong> - 只显示Unix域套接字</li><li><strong>-f FAMILY</strong> - 显示FAMILY套接字的类型。目前支持下面这些族：unix、inet、inet6、link、netlink。</li><li><strong>-A QUERY</strong> - 指定要列出的套接字列表，通过逗号分隔。可以识别下面的标识符：all、inet、tcp、udp、raw、unix、packet、netlink、unix_dgram、unix_stream、packet_raw、packet_dgram。</li><li><strong>-o STATUS</strong> - 列出指定状态的套接字</li></ul><h3 id="ss-命令示例" tabindex="-1">ss 命令示例 <a class="header-anchor" href="#ss-命令示例" aria-label="Permalink to “ss 命令示例”">​</a></h3><p><strong>1.</strong> 显示所有的的TCP端口和使用它们的进程：</p><pre><code># ss -tnap
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-tnap.jpg" alt="ss tnap"></p><p><strong>2.</strong> 你可以使用-4 标志来显示IPv4链接，-6标志来显示IPv6链接，比如：</p><pre><code># ss -tnap6
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-tnap6.jpg" alt="ss tnap6"></p><p><strong>3.</strong> 跟上面的行为一样，你只需用u代替t就会显示所有开放的UDP端口。</p><pre><code># ss -unap
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-unap.jpg" alt="ss unap"></p><p><strong>4.</strong> 你可以使用-s标志来打印各种有用的统计数据：</p><pre><code># ss -s
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-stats.jpg" alt="ss stats"></p><p><strong>5.</strong> 你可以使用-o标志来检查所有不同状态下的链接，比如显示所有已经建立的连接。</p><pre><code># ss -tn -o state established -p
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-est.jpg" alt="ss est"></p><hr>`,22)),i("p",null,[t[1]||(t[1]=s("via: ",-1)),o(n,{href:"http://linoxide.com/linux-command/ss-sockets-network-connection/"},{default:e(()=>[...t[0]||(t[0]=[s("http://linoxide.com/linux-command/ss-sockets-network-connection/",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=s("作者：",-1)),o(n,{href:"http://linoxide.com/author/adriand/"},{default:e(()=>[...t[2]||(t[2]=[s("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=s(" 译者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[3]||(t[3]=[s("geekpi",-1)])]),_:1}),t[7]||(t[7]=s(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=s("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[s("Linux中国",-1)])]),_:1}),t[12]||(t[12]=s(" 荣誉推出",-1))])])}const w=r(g,[["render",u]]);export{L as __pageData,w as default};
